import{z as n,x as s,o as e,c as i,q as B,j as A,D as E,d as t,s as r,S as o}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"超参的缩放规则","description":"","frontmatter":{"title":"超参的缩放规则","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pf2-hparam-scaling-rules.md","filePath":"llm/pf2-hparam-scaling-rules.md","lastUpdated":1791413859000}'),h={name:"llm/pf2-hparam-scaling-rules.md"};function c(p,a,d,m,C,D){const l=s("Mermaid");return e(),i("div",null,[a[2]||(a[2]=B('<h1 id="超参的缩放规则" tabindex="-1">超参的缩放规则 <a class="header-anchor" href="#超参的缩放规则" aria-label="Permalink to &quot;超参的缩放规则&quot;">​</a></h1><div class="epigraph"><p>大模型的学习率不是在大模型上找到的，而是在小模型上定好、按标度规则搬上去的；搬运规则本身才是要管理的东西。</p><footer>—— 据 Yang &amp; Hu, Tensor Programs V（μP）与 Goyal et al., 2017 的大 batch 规则整理</footer></div><p><a href="/llm/pf2-data-mix-final">上一课</a>定下配比与总 token 数，超参只剩一组决定。目标规模的运行只有一次机会，网格搜索在大模型上不可负担，所以问题变成：哪些超参在小代理上扫、按什么规则迁移到目标规模、迁移的担保边界在哪。<a href="/llm/lr-sensitivity-mup-practice">μP 的实践</a>与<a href="/llm/lr-batch-scaling-law">学习率随 batch 的规则</a>已经把两条主轴讲过，本课把它们组装成开工前可执行的一套缩放规则，并写清它管不着什么。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>小代理上扫出的峰值学习率直接搬到大模型，常以发散或欠优收场：宽度和深度变了，更新的合理尺度就变了；batch 变了，学习率与噪声的平衡也变了。失败的典型是把「扫出来的数」当结论带走，而把「扫的坐标系」扔掉——超参是绑定在宽度、深度、batch、序列长这些坐标上的函数，不声明坐标系就没有可比性。第二个失败是反向的：把某一次拟合的标度律当定理，搬到换了优化器、换了词表、加了稳定件的新配方上，谷底已经移走。</p><p><span class="marginnote">「coord check」（坐标检查）就是在两三个小宽度上验证「各层更新的幅度是否像 μP 预言的那样随宽度变化」——像搬家前先试一次电梯装不装得下，确认了再搬整栋楼的家具。</span></p><h3 id="一条规则的三个部件" tabindex="-1">一条规则的三个部件 <a class="header-anchor" href="#一条规则的三个部件" aria-label="Permalink to &quot;一条规则的三个部件&quot;">​</a></h3><p>每条缩放规则都要写全三部件。<strong>原点</strong>：在哪个代理规模、哪套稳定件组合下扫描；词表与稳定件不进原点，规则失效。<strong>标度</strong>：随哪个变量怎么变——μP 按宽度重标初始化与学习率，使不同宽度下都做特征学习；batch 规则给出临界 batch 之下学习率随 \\(B\\) 线性放大、之上只换墙钟的分割。<strong>校验</strong>：迁移到目标规模前用 coord check 验证——看各层更新幅度对宽度是否如预期，不看代理损失是否碰巧都降。三部件缺一，这条规则就不许进配方。</p>',8)),(e(),A(o,null,{default:E(()=>[r(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%BB%A3%E7%90%86%E8%A7%84%E6%A8%A1%20%2B%20%E7%A8%B3%E5%AE%9A%E4%BB%B6%E5%AE%9A%E5%8E%9F%E7%82%B9%22%5D%20--%3E%20B%5B%22%E6%89%AB%E6%8F%8F%EF%BC%9A%E5%AD%A6%E4%B9%A0%E7%8E%87%E5%AF%B9%E6%95%B0%E5%8F%96%E7%82%B9%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%86%99%E5%87%BA%E6%A0%87%E5%BA%A6%EF%BC%9A%E9%9A%8F%E5%AE%BD%E5%BA%A6%20%2F%20batch%20%E6%80%8E%E4%B9%88%E5%8F%98%22%5D%0A%20%20C%20--%3E%20D%7B%22coord%20check%20%E9%80%9A%E8%BF%87%EF%BC%9F%22%7D%0A%20%20D%20--%3E%7C%E5%90%A6%7C%20A%0A%20%20D%20--%3E%7C%E6%98%AF%7C%20E%5B%22%E7%9B%AE%E6%A0%87%E8%A7%84%E6%A8%A1%E4%B8%80%E6%AC%A1%E7%82%B9%E7%81%AB%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实操顺序：先冻结<a href="/llm/z-loss">稳定件</a>与<a href="/llm/adamw">优化器</a>——它们是原点的一部分，之后换 Muon 这类矩阵优化器就要重走一遍网格；再在两三个宽度上跑 coord check 确认目标真是 μP 口径；然后对数取点扫峰值学习率，耦合维度（如 \\(\\lambda\\) 与 \\(\\eta\\) 的挂法）声明成单一自由度；最后把规则写成表格随配方升版：每个超参一行，列出原点值、标度式与校验状态。扫描预算遵守<a href="/llm/ti-hparam-search-eng">超参搜索工程</a>的封顶口径——约一成预算做搜索，产出响应面归档，成为下次的先验。</p><p><span class="marginnote">μP 的担保表只有宽度：深度、序列长、词表、batch 的极端区都不在定理范围内；换优化器（如 Muon）更要在目标规模附近单独网格。把「μP 迁移超参」读成「一切维度都免扫」，是最常见的误用。</span></p><p><span class="marginnote">数字实例：若一次点火预算 100 万卡时，按约一成的口径，留给超参扫描的就是约 10 万卡时——在尺寸缩小百倍的代理上这够跑几十条短曲线；这些曲线的结论，换来目标规模「只点一次火」的底气。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么规则三部件缺一不可：原点缺失则两条曲线不可比——换了稳定件，敏感度谷的位置本身会移；标度缺失则只有孤立的数，宽度一变就作废；校验缺失则不知道标度在本次配方上是否成立——小代理复现不稳是有文献记录的失败（Wortsman et al., ICLR 2024）。缩放规则的本质是把「在哪搜索」的决策从目标规模挪到代理规模：目标规模上只做一次有校验背书的点火，而不是用全价卡时当搜索算力的燃料。这与 Chinchilla 用约四百次运行支撑拟合面是同一经济学：便宜的尺度买信息，贵的尺度花信息。</p><p><span class="marginnote">直觉类比：缩放规则像用风洞代替真机试飞——风洞（小代理）里便宜地试出机翼角度的规律，再按相似准则换算到真机；没有换算准则（标度）或不上天复核（校验），风洞数据反而会误导。</span></p>',7)),(e(),A(o,null,{default:E(()=>[r(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%B8%89%E9%83%A8%E4%BB%B6%E5%90%84%E8%87%AA%E7%BC%BA%E4%B8%80%EF%BC%8C%E4%BC%9A%E6%80%8E%E4%B9%88%E5%9D%8F%EF%BC%9F%22%5D%20--%3E%20B%5B%22%E7%BC%BA%E5%8E%9F%E7%82%B9%22%5D%0A%20%20A%20--%3E%20C%5B%22%E7%BC%BA%E6%A0%87%E5%BA%A6%22%5D%0A%20%20A%20--%3E%20D%5B%22%E7%BC%BA%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E6%8D%A2%E4%BA%86%E7%A8%B3%E5%AE%9A%E4%BB%B6%EF%BC%8C%E8%B0%B7%E7%9A%84%E4%BD%8D%E7%BD%AE%E7%A7%BB%E5%8A%A8%EF%BC%8C%E6%9B%B2%E7%BA%BF%E4%B8%8D%E5%8F%AF%E6%AF%94%22%5D%0A%20%20C%20--%3E%20C1%5B%22%E5%8F%AA%E5%89%A9%E5%AD%A4%E7%AB%8B%E7%9A%84%E6%95%B0%EF%BC%8C%E5%AE%BD%E5%BA%A6%E4%B8%80%E5%8F%98%E5%B0%B1%E4%BD%9C%E5%BA%9F%22%5D%0A%20%20D%20--%3E%20D1%5B%22%E5%B0%8F%E4%BB%A3%E7%90%86%E5%A4%8D%E7%8E%B0%E4%B8%8D%E7%A8%B3%E6%97%A0%E4%BA%BA%E5%8F%91%E7%8E%B0%EF%BC%8C%E7%82%B9%E7%81%AB%E7%BF%BB%E8%BD%A6%22%5D%0A%20%20B1%20--%3E%20E%5B%22%E7%BB%93%E5%B1%80%EF%BC%9A%E6%8B%BF%E5%85%A8%E4%BB%B7%E7%82%B9%E7%81%AB%E8%B5%8C%E4%B8%80%E4%B8%AA%E6%B2%A1%E8%83%8C%E4%B9%A6%E7%9A%84%E8%B6%85%E5%8F%82%22%5D%0A%20%20C1%20--%3E%20E%0A%20%20D1%20--%3E%20E%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=B('<p>这张图回答的是「三部件各管哪一类失效」：原点管可比性，标度管可迁移性，校验管本次配方上的真实性，任何一角缺失都退化成全价赌博。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课管优化侧超参的迁移：学习率、batch、初始化、衰减的挂法。架构轴的标度——参数与 token 怎么随算力放大——是<a href="/llm/kaplan-scaling">缩放律</a>与<a href="/llm/scaling-law-fitting">其拟合方法</a>的事，本课只要求规模落点写进<a href="/llm/pf2-pretrain-checklist">检查清单</a>。数据侧的配比迁移（小模型求权重、大模型使用）上一课已写，属于另一条通道。日程随总步数的缩放是学习率日程课的主题，这里只钉一句：日程寿命与训练长度耦合，本身是要随规则一起缩放的对象。规则之外永远保留例外通道：目标规模上首轮观测若显示谷在网格外，停下来扩网格，不要外推硬点火。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>缩放规则三部件：原点（代理规模加稳定件）、标度（随哪个变量怎么变）、校验（coord check）。</li><li>μP 只担保宽度；深度、序列长、词表与换优化器都要单独网格。</li><li>batch 规则在临界点两侧含义不同：之下是 token 效率工具，之上只换墙钟。</li><li>扫描预算封顶约一成，响应面连同失败点归档为下次先验。</li><li>出处：Yang &amp; Hu, Tensor Programs V；Goyal et al., 2017 与 Shallue et al., 2019；Wortsman et al., ICLR 2024 对小代理迁移不稳的记录。</li></ul>',5))])}const u=n(h,[["render",c]]);export{_ as __pageData,u as default};
